def initiative_order(units):
    """units: [(name, speed, roll)]. Names in acting order: highest speed+roll first, then higher speed, then name."""
    return [u[0] for u in sorted(units, key=lambda u: (-(u[1] + u[2]), -u[1], u[0]))]

